import dspy
from dspy.utils.exceptions import ContextWindowExceededError

def echo(text: str) -> str:
    return f'Echoed: {text}'

react = dspy.ReAct('input_text -> output_text', tools=[echo])
state = {'n': 0}
def fake_react(**kwargs):
    i = state['n']
    state['n'] += 1
    if i < 2:
        return dspy.Prediction(next_thought=f'Thought {i+1}', next_tool_name='echo', next_tool_args={'text': f'Text {i+1}'})
    if i == 2:
        raise ContextWindowExceededError()
    return dspy.Prediction(next_thought='Final', next_tool_name='finish', next_tool_args={})

react.react = fake_react
react.extract = lambda **kwargs: dspy.Prediction(output_text='Final output')
out = react(input_text='x')

assert out.output_text == 'Final output'
for k in ['thought_0', 'tool_name_0', 'tool_args_0', 'observation_0']:
    assert k not in out.trajectory
assert 'thought_1' in out.trajectory and 'thought_2' in out.trajectory
print(sorted(out.trajectory.keys()))
print(out.output_text)
