import dspy
from dspy.utils.dummies import DummyLM

class Sig(dspy.Signature):
    question: str = dspy.InputField()
    tools: list[dspy.Tool] = dspy.InputField()
    answer: str = dspy.OutputField()
    tool_calls: dspy.ToolCalls = dspy.OutputField()

def weather(city: str) -> str:
    return city

class LM(DummyLM):
    def __init__(self):
        super().__init__([{'answer': 'sunny', 'tool_calls': {'tool_calls': []}}], adapter=dspy.JSONAdapter())
        self.formats = []
    @property
    def supported_params(self):
        return {'response_format'}
    @property
    def supports_response_schema(self):
        return True
    def forward(self, prompt=None, messages=None, **kwargs):
        self.formats.append(kwargs.get('response_format'))
        return super().forward(prompt=prompt, messages=messages, **kwargs)

lm = LM()
with dspy.context(lm=lm, adapter=dspy.JSONAdapter(use_native_function_calling=False)):
    out = dspy.Predict(Sig)(question='weather?', tools=[dspy.Tool(weather)])

assert lm.formats[0] == {'type': 'json_object'}
assert out.answer == 'sunny'
assert out.tool_calls == dspy.ToolCalls(tool_calls=[])
print(lm.formats[0])
print(out.answer, out.tool_calls.model_dump())
